package org.zhbot;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.*;
import java.text.NumberFormat;

public class StackTooltipsOverlay extends WidgetItemOverlay {
    private final Client client;
    private final TooltipManager tooltipManager;

    @Inject
    private StackTooltipsOverlay(Client client, TooltipManager tooltipManager)
    {
        this.client = client;
        this.tooltipManager = tooltipManager;

        showOnBank();
        showOnInventory();
        showOnEquipment();
        showOnInterfaces(InterfaceID.SHARED_BANK_SIDE);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (client.isMenuOpen())
            return;

        if (widgetItem.getDraggingCanvasBounds() != null)
            return;

        var quantity = widgetItem.getQuantity();
        if (quantity < 100000)
            return;

        var mousePosition = client.getMouseCanvasPosition();
        if (!widgetItem.getCanvasBounds().contains(mousePosition.getX(), mousePosition.getY()))
            return;

        tooltipManager.add(new Tooltip("Quantity: " + NumberFormat.getNumberInstance().format(quantity)));
    }
}

package org.zhbot;

import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Stack Tooltips",
	tags = {"item", "stack", "quantity", "tooltips"}
)
public class StackTooltipsPlugin extends Plugin
{
	@Inject
    OverlayManager overlayManager;

	@Inject
	private StackTooltipsOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
	}
}

package org.zhbot;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class StackTooltipsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(StackTooltipsPlugin.class);
		RuneLite.main(args);
	}
}
